import base64, json, mimetypes, os, sys
from openai import OpenAI

client = OpenAI(
    base_url=os.environ["AZURE_OPENAI_ENDPOINT"].rstrip("/") + "/openai/v1/",
    api_key=os.environ["AZURE_OPENAI_API_KEY"],
)
MODEL = os.environ["VISION_DEPLOYMENT"]

def to_image_part(source, detail="auto"):
    if source.startswith("http"):
        url = source
    else:
        mime = mimetypes.guess_type(source)[0] or "image/jpeg"
        with open(source, "rb") as f:
            b64 = base64.b64encode(f.read()).decode("utf-8")
        url = f"data:{mime};base64,{b64}"
    return {"type": "input_image", "image_url": url, "detail": detail}

def describe(source):
    r = client.responses.create(
        model=MODEL,
        instructions="Describe imágenes de forma objetiva, en español y en 3 viñetas.",
        input=[{"role": "user", "content": [
            {"type": "input_text", "text": "¿Qué muestra esta imagen?"},
            to_image_part(source),
        ]}],
    )
    return r.output_text

if __name__ == "__main__":
    print(describe(sys.argv[1]))
